package com.enterprisegrid.gateway.filter;

import org.springframework.cloud.gateway.filter.GatewayFilter;
import org.springframework.cloud.gateway.filter.factory.AbstractGatewayFilterFactory;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.core.context.ReactiveSecurityContextHolder;
import org.springframework.stereotype.Component;

@Component
public class TenantHeaderFilter extends AbstractGatewayFilterFactory<TenantHeaderFilter.Config> {

    public TenantHeaderFilter() {
        super(Config.class);
    }

    @Override
    public GatewayFilter apply(Config config) {
        return (exchange, chain) -> ReactiveSecurityContextHolder.getContext()
                .map(sc -> sc.getAuthentication().getPrincipal())
                .cast(Jwt.class)
                .flatMap(jwt -> {
                    String verifiedTenantId = jwt.getClaimAsString("tenantId");
                    // Overwrite client header with authenticated claim
                    var mutatedRequest = exchange.getRequest().mutate()
                            .header("X-Tenant-Id", verifiedTenantId)
                            .build();
                    return chain.filter(exchange.mutate().request(mutatedRequest).build());
                });
    }

    public static class Config {}
}
